import{_ as o,o as d,c as t,a5 as c}from"./chunks/framework.DJo0M80U.js";const l=JSON.parse('{"title":"Vue 异步请求适合放在哪个生命周期里调用","description":"得看实际情况； 一般在 created 里面就可以，如果涉及到需要页面加载完成之后的操作话就用 mounted ； created 阶段的优势是：请求时间比较早，页面 loading 时间相对较短； mounted 阶段的优势是：页面已经渲染完成，如果想请求之后进行 DOM 操作。","frontmatter":{"title":"Vue 异步请求适合放在哪个生命周期里调用","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","项目实战"],"description":"得看实际情况； 一般在 created 里面就可以，如果涉及到需要页面加载完成之后的操作话就用 mounted ； created 阶段的优势是：请求时间比较早，页面 loading 时间相对较短； mounted 阶段的优势是：页面已经渲染完成，如果想请求之后进行 DOM 操作。","sidebarWeight":41,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/实战/Vue 异步请求适合放在哪个生命周期里调用.md"},"headers":[],"relativePath":"posts/Vue系统教程/07-项目实战/Vue 异步请求适合放在哪个生命周期里调用.md","filePath":"posts/Vue系统教程/07-项目实战/Vue 异步请求适合放在哪个生命周期里调用.md"}'),a={name:"posts/Vue系统教程/07-项目实战/Vue 异步请求适合放在哪个生命周期里调用.md"};function u(r,e,_,n,s,i){return d(),t("div",null,[...e[0]||(e[0]=[c('<div><h1 id="vue-异步请求适合放在哪个生命周期里调用" tabindex="-1">Vue 异步请求适合放在哪个生命周期里调用 <a class="header-anchor" href="#vue-异步请求适合放在哪个生命周期里调用" aria-label="Permalink to &quot;Vue 异步请求适合放在哪个生命周期里调用&quot;">​</a></h1><blockquote><p>本节目标：理解“Vue 异步请求适合放在哪个生命周期里调用”的核心思路，并能把它用于实际开发或面试表达。 得看实际情况； 一般在 <code>created</code> 里面就可以，如果涉及到需要页面加载完成之后的操作话就用 <code>mounted</code>； <code>created</code> 阶段的优势是：请求时间比较早，页面 <code>loading</code> 时间相对较短； <code>mounted</code> 阶段的优势是：页面已经渲染完成，如果想请求之后进行 <code>DOM</code> 操作的话，必须在 <code>mounted</code> 阶段发起请求；</p></blockquote><p><code>vue</code>请求数据放在<code>created</code>好还是<code>mounted</code>里好 建议放在<code>created</code>里 <code>created:</code>在模板渲染成<code>html</code>前调用，即通常初始化某些属性值，然后再渲染成视图。 <code>mounted:</code>在模板渲染成<code>html</code>后调用，通常是初始化页面完成后，再对<code>html</code>的<code>dom</code>节点进行一些需要的操作。</p><p>如果在<code>mounted</code>钩子函数中请求数据可能导致页面闪屏问题 其实就是加载时机问题，放在<code>created</code>里会比<code>mounted</code>触发早一点，如果在页面挂载完之前请求完成的话就不会看到闪屏了</p></div>',1)])])}const p=o(a,[["render",u]]);export{l as __pageData,p as default};
